  edit(taskId: number, newPriority: number): void { this.info.get(taskId)![1] = newPriority; }
  remove(taskId: number): void { this.info.delete(taskId); }
  runTop(): number {
    let bestId = -1, bestP = -1;
    for (const [id, [, p]] of this.info) {
      if (p > bestP || (p === bestP && id > bestId)) { bestP = p; bestId = id; }
